"use client";

import Link from "next/link";
import { useLiveQuery } from "dexie-react-hooks";
import { ArrowLeft, ImagePlus, Maximize2, Trash2, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { db, importImageFile } from "@/lib/db";
import type { ImageRecord } from "@/types/workshop";

const GALLERY_SETTING_KEY = "archive-gallery-image-ids";

function GalleryImage({ image }: { image: ImageRecord }) {
  const imageRef = useRef<HTMLImageElement>(null);
  useEffect(() => {
    const url = URL.createObjectURL(image.blob);
    if (imageRef.current) imageRef.current.src = url;
    return () => URL.revokeObjectURL(url);
  }, [image.blob]);
  return <img ref={imageRef} alt={image.altText || image.title} draggable={false} />;
}

export function ArchiveGallery() {
  const inputRef = useRef<HTMLInputElement>(null);
  const allImages = useLiveQuery(() => db.images.orderBy("createdAt").toArray(), [], []);
  const [galleryIds, setGalleryIds] = useState<string[]>([]);
  const [initialized, setInitialized] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [importing, setImporting] = useState(false);
  const [notice, setNotice] = useState("");
  const [lightboxOpen, setLightboxOpen] = useState(false);

  useEffect(() => {
    if (initialized) return;
    void db.settings.get(GALLERY_SETTING_KEY).then(async (record) => {
      const existingIds = new Set(allImages.map((image) => image.id));
      const ids = Array.isArray(record?.value)
        ? (record.value as string[]).filter((id) => existingIds.has(id))
        : allImages.map((image) => image.id);
      setGalleryIds(ids);
      if (!Array.isArray(record?.value)) await db.settings.put({ key: GALLERY_SETTING_KEY, value: ids });
      setInitialized(true);
    });
  }, [allImages, initialized]);

  const imageMap = useMemo(() => new Map(allImages.map((image) => [image.id, image])), [allImages]);
  const galleryImages = useMemo(
    () => galleryIds.map((id) => imageMap.get(id)).filter((image): image is ImageRecord => Boolean(image)),
    [galleryIds, imageMap],
  );
  const selected = galleryImages.find((image) => image.id === selectedId) ?? galleryImages[0];

  const announce = useCallback((message: string) => {
    setNotice(message);
    window.setTimeout(() => setNotice(""), 2800);
  }, []);

  const persistIds = useCallback(async (ids: string[]) => {
    setGalleryIds(ids);
    await db.settings.put({ key: GALLERY_SETTING_KEY, value: ids });
  }, []);

  const importFiles = useCallback(async (files: FileList | File[]) => {
    const candidates = Array.from(files).filter((file) => file.type.startsWith("image/"));
    if (!candidates.length) return announce("没有找到可导入的图片文件。");
    setImporting(true);
    try {
      const imported: ImageRecord[] = [];
      for (const file of candidates) imported.push(await importImageFile(file));
      await persistIds([...galleryIds, ...imported.map((image) => image.id)]);
      setSelectedId(imported[0]?.id ?? selectedId);
      announce(`已加入 ${imported.length} 张图片。`);
    } catch (error) {
      console.error(error);
      announce("导入失败，请检查图片后重试。");
    } finally {
      setImporting(false);
    }
  }, [announce, galleryIds, persistIds, selectedId]);

  const removeSelected = useCallback(async () => {
    if (!selected) return;
    const next = galleryIds.filter((id) => id !== selected.id);
    await persistIds(next);
    setSelectedId(next[0] ?? null);
    setLightboxOpen(false);
    announce(`已将「${selected.title}」移出画廊，原图片仍保留在素材库。`);
  }, [announce, galleryIds, persistIds, selected]);

  return (
    <main className="archive-gallery-shell">
      <header className="archive-gallery-toolbar">
        <Link href="/" className="archive-gallery-back"><ArrowLeft size={17} /> 返回总主页</Link>
        <div className="archive-gallery-title"><span>WRITING TIME / GALLERY</span><strong>拾光画廊</strong></div>
        <div className="archive-gallery-actions">
          <span>{galleryImages.length.toString().padStart(2, "0")} IMAGES</span>
          <button type="button" onClick={() => inputRef.current?.click()} disabled={importing}><ImagePlus size={17} />{importing ? "导入中" : "新增档案"}</button>
        </div>
      </header>

      {initialized && galleryImages.length ? (
        <section className="archive-gallery-layout">
          <div className="archive-gallery-grid" aria-label="画廊图片">
            {galleryImages.map((image) => (
              <button
                key={image.id}
                className="archive-gallery-item"
                data-selected={selected?.id === image.id}
                type="button"
                onClick={() => setSelectedId(image.id)}
                onDoubleClick={() => { setSelectedId(image.id); setLightboxOpen(true); }}
                aria-label={`选择图片：${image.title}`}
                aria-pressed={selected?.id === image.id}
              >
                <GalleryImage image={image} />
                <span>{image.title}</span>
              </button>
            ))}
          </div>

          <aside className="archive-image-inspector">
            {selected ? <>
              <div className="archive-image-heading"><span>SELECTED IMAGE</span><b>{selected.title}</b></div>
              <button className="archive-image-preview" type="button" onClick={() => setLightboxOpen(true)}><GalleryImage image={selected} /></button>
              <div className="archive-image-meta">
                <span>{selected.name}</span>
                <span>{selected.width ?? "?"} × {selected.height ?? "?"} · {selected.mimeType || "IMAGE"}</span>
                <span>{selected.tags.length ? selected.tags.join(" · ") : "无标签"}</span>
              </div>
              <div className="archive-image-controls">
                <button type="button" onClick={() => setLightboxOpen(true)}><Maximize2 size={16} /> 浏览大图</button>
                <button className="danger" type="button" onClick={() => void removeSelected()}><Trash2 size={16} /> 移出画廊</button>
              </div>
            </> : null}
          </aside>
        </section>
      ) : initialized ? (
        <section className="archive-gallery-empty">
          <ImagePlus size={38} strokeWidth={1.3} />
          <h2>画廊中还没有图片</h2>
          <p>添加图片后，就可以在这里挑选和浏览。</p>
          <button type="button" onClick={() => inputRef.current?.click()}>选择图片</button>
        </section>
      ) : <div className="archive-gallery-loading">正在读取本地图片……</div>}

      <input ref={inputRef} hidden type="file" multiple accept="image/*" onChange={(event) => {
        if (event.currentTarget.files) void importFiles(event.currentTarget.files);
        event.currentTarget.value = "";
      }} />
      <p className="archive-gallery-toast" data-visible={Boolean(notice)}>{notice}</p>

      {lightboxOpen && selected ? <div className="archive-gallery-lightbox" role="dialog" aria-modal="true">
        <button type="button" className="archive-lightbox-close" onClick={() => setLightboxOpen(false)} aria-label="关闭"><X /></button>
        <GalleryImage image={selected} />
        <div><strong>{selected.title}</strong><span>{selected.width ?? "?"} × {selected.height ?? "?"}</span></div>
      </div> : null}
    </main>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from 'react';
import { prepareMapAssets } from '@/lib/home/world-map';

export type Scene = 'home' | 'map';
export type Phase = 'idle' | 'covering' | 'covered' | 'revealing' | 'error';
const STALE = Symbol('stale transition');
const waitFrame = () => new Promise<void>(resolve => requestAnimationFrame(() => resolve()));

export function usePortalTransition() {
  const [scene, setScene] = useState<Scene>('home');
  const [phase, setPhase] = useState<Phase>('idle');
  const [target, setTarget] = useState<Scene>('home');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [booting, setBooting] = useState(true);
  const fog = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<Scene>('home');
  const phaseRef = useRef<Phase>('idle');
  const targetRef = useRef<Scene>('home');
  const id = useRef(0);
  const progress = useRef(0);
  const mounted = useRef(true);
  const reduced = useRef(false);

  const changePhase = useCallback((next: Phase) => { phaseRef.current = next; setPhase(next); }, []);
  const animate = useCallback((to: number, duration: number, transitionId: number) => new Promise<void>((resolve, reject) => {
    const start = performance.now(), from = progress.current;
    const tick = (time: number) => {
      if (!mounted.current || transitionId !== id.current) { reject(STALE); return; }
      const t = duration ? Math.min(1, (time - start) / duration) : 1;
      const eased = t * t * (3 - 2 * t);
      progress.current = from + (to - from) * eased;
      if (fog.current) fog.current.style.opacity = String(progress.current);
      if (t < 1) requestAnimationFrame(tick); else resolve();
    };
    requestAnimationFrame(tick);
  }), []);

  const requestScene = useCallback((requested: Scene, retry = false) => {
    const current = sceneRef.current;
    if (phaseRef.current === 'idle' && requested === current) return;
    if (phaseRef.current !== 'idle' && requested === targetRef.current && !retry) return;
    const transitionId = ++id.current;
    targetRef.current = requested;
    setTarget(requested); setError(''); setLoading(false);
    const run = async () => {
      try {
        if (requested !== current) {
          changePhase('covering');
          await animate(1, reduced.current ? 120 : Math.max(80, 380 * (1 - progress.current)), transitionId);
          changePhase('covered');
          // Paint the opaque frame before changing which scene is active.
          await waitFrame(); await waitFrame();
          if (transitionId !== id.current) throw STALE;
          if (requested === 'map') {
            const feedback = window.setTimeout(() => { if (id.current === transitionId) setLoading(true); }, 700);
            let timeout: number | undefined;
            try {
              await Promise.race([prepareMapAssets(retry), new Promise<never>((_, reject) => { timeout = window.setTimeout(() => reject(new Error('地图加载超时，请重试。')), 8000); })]);
            } finally { window.clearTimeout(feedback); if (timeout) window.clearTimeout(timeout); if (id.current === transitionId) setLoading(false); }
          }
          if (transitionId !== id.current) throw STALE;
          if (requested === 'map') {
            const deadline = performance.now() + 1200;
            while (!document.querySelector('.world-map[data-ready="true"]')) {
              if (transitionId !== id.current) throw STALE;
              if (performance.now() > deadline) throw new Error('地图布局暂时不可用，请重试。');
              await waitFrame();
            }
          }
          sceneRef.current = requested; setScene(requested);
          try { sessionStorage.setItem('writing-time-map-scene-v1', requested); } catch { /* storage may be disabled */ }
          await waitFrame(); await waitFrame();
          if (transitionId !== id.current) throw STALE;
        }
        changePhase('revealing');
        await animate(0, reduced.current ? 130 : Math.max(80, 480 * progress.current), transitionId);
        if (transitionId !== id.current) throw STALE;
        changePhase('idle');
      } catch (cause) {
        if (cause === STALE || transitionId !== id.current || !mounted.current) return;
        progress.current = 1;
        if (fog.current) fog.current.style.opacity = '1';
        setError(cause instanceof Error ? cause.message : '地图暂时无法展开。');
        changePhase('error');
      }
    };
    void run();
  }, [animate, changePhase]);

  useEffect(() => {
    mounted.current = true;
    const preference = matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => { reduced.current = preference.matches; };
    update(); preference.addEventListener('change', update);
    let saved: string | null = null;
    try { saved = sessionStorage.getItem('writing-time-map-scene-v1'); } catch { /* storage may be disabled */ }
    const bootId = id.current;
    if (saved === 'map') {
      progress.current = 1;
      if (fog.current) fog.current.style.opacity = '1';
      queueMicrotask(() => { if (mounted.current && id.current === bootId) changePhase('covered'); });
      prepareMapAssets().then(async () => {
        if (!mounted.current || id.current !== bootId) return;
        sceneRef.current = 'map'; setScene('map');
        await waitFrame(); await waitFrame();
        if (!mounted.current || id.current !== bootId) return;
        const deadline = performance.now() + 1200;
        while (!document.querySelector('.world-map[data-ready="true"]')) {
          if (!mounted.current || id.current !== bootId) return;
          if (performance.now() > deadline) throw new Error('地图布局暂时不可用，请重试。');
          await waitFrame();
        }
        setBooting(false); changePhase('revealing');
        await animate(0, reduced.current ? 130 : 480, bootId);
        if (mounted.current && id.current === bootId) changePhase('idle');
      }).catch(cause => { if (mounted.current) { setBooting(false); setError(cause instanceof Error ? cause.message : '地图暂时无法展开。'); changePhase('error'); } });
    } else queueMicrotask(() => { if (mounted.current && id.current === bootId) setBooting(false); });
    return () => { mounted.current = false; id.current++; preference.removeEventListener('change', update); };
  }, [animate, changePhase]);

  const returnHome = useCallback(() => {
    if (phaseRef.current === 'error') { ++id.current; setError(''); setBooting(false); sceneRef.current = 'home'; setScene('home'); progress.current = 0; if (fog.current) fog.current.style.opacity = '0'; changePhase('idle'); try { sessionStorage.setItem('writing-time-map-scene-v1', 'home'); } catch {} return; }
    requestScene('home');
  }, [requestScene, changePhase]);
  return { scene, phase, target, error, loading, booting, fog, requestScene, returnHome };
}
